def bst_contains(root, key):
    node = root
    while node is not None:
        if key == node[0]:
            return True
        if key < node[0]:
            node = node[1]
        else:
            node = node[2]
    return False

root = [5, [2, None, [3, None, None]], [8, None, None]]

print(bst_contains(root, 3))
print(bst_contains(root, 7))
print(bst_contains(None, 3))

def bst_range(root, low, high):
    if low > high:
        raise ValueError("invalid range")
    result = []
    def visit(node):
        if node is None:
            return
        key, left, right = node
        if key > low:
            visit(left)
        if low <= key <= high:
            result.append(key)
        if key < high:
            visit(right)
    visit(root)
    return result

root = [5, [2, None, [3, None, None]], [8, None, None]]

print(bst_range(root, 3, 8))
print(bst_range(root, 6, 7))
print(bst_range(None, 0, 9))
try:
    bst_range(root, 9, 1)
except ValueError:
    print("ValueError")
